  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_efc_type_role` (`ticket_type`,`role_value`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- BASE TABLE: office_days
DROP TABLE IF EXISTS `office_days`;
